            const auto half = count / 2;
            const auto mid = lo + half;
            const bool before = Strict ? tails[mid] < v[i] : !(v[i] < tails[mid]);
            lo = before ? mid + 1 : lo;
            count = before ? count - half - 1 : half;
        }
        if (lo != 0 && lo != length) ++searches;
        tails[lo] = v[i];
        length += lo == length;
    }
