// SPDX-License-Identifier: CC0-1.0
#include SOURCE
#include <cassert>
#include <iostream>
#include <random>

std::size_t checks=0;
#if !defined(SIRKIT_DISABLE_SIMD) && defined(__GNUC__) && !defined(__clang__) && __GNUC__ == 15 && __GNUC_MINOR__ == 2 && defined(__x86_64__)
__attribute__((target("avx2")))
std::size_t test_candidate_search(const std::vector<std::int64_t>& values, std::int64_t key_value) {
        std::size_t lo = 1, count = values.size() - 2;
        if (count >= 32 && count <= 4096) {
            const auto key = _mm256_set1_epi64x(key_value);
            while (count >= 32) {
                const auto quarter = count / 4;
                const auto p0 = lo + quarter, p1 = p0 + quarter, p2 = p1 + quarter;
                const auto samples = _mm256_set_epi64x(0, values[p2], values[p1], values[p0]);
                const auto mask = _mm256_cmpgt_epi64(key, samples);
                const auto offsets = _mm256_set_epi64x(0, quarter, quarter, quarter + 1);
                const auto weighted = _mm256_and_si256(mask, offsets);
                const auto halves = _mm_add_epi64(_mm256_castsi256_si128(weighted), _mm256_extracti128_si256(weighted, 1));
                const auto sum = _mm_add_epi64(halves, _mm_srli_si128(halves, 8));
                lo += static_cast<std::size_t>(_mm_cvtsi128_si64(sum));
                const auto m0 = static_cast<std::size_t>(_mm256_extract_epi64(mask, 0));
                const auto m2 = static_cast<std::size_t>(_mm256_extract_epi64(mask, 2));
                // q+m0は符号なし演算でq-b0に一致する。
                count = quarter + m0 + ((count % 4) & m2);
            }
        }
        while (count != 0) {
            const auto half = count / 2, mid = lo + half;
            const bool before = values[mid] < key_value;
            lo = before ? mid + 1 : lo;
            count = before ? count - half - 1 : half;
        }
    return lo;
}
#endif

template<bool Strict, class T>
std::size_t slow_length(const std::vector<T>& values) {
    std::vector<std::size_t> lengths(values.size(),1);
    std::size_t answer=0;
    for(std::size_t i=0;i<values.size();++i) {
        for(std::size_t j=0;j<i;++j)
            if(Strict ? values[j]<values[i] : !(values[i]<values[j]))
                lengths[i]=std::max(lengths[i], lengths[j]+1);
        answer=std::max(answer,lengths[i]);
    }
    return answer;
}
template<bool Strict, class T>
void sequence_check(const std::vector<T>& values) {
    const auto saved=values;
    const auto result=reinsirk::detail::LISIndicesWithValues<Strict,std::uint32_t>(values);
#if !defined(SIRKIT_DISABLE_SIMD) && defined(__GNUC__) && !defined(__clang__) && __GNUC__ == 15 && __GNUC_MINOR__ == 2 && defined(__x86_64__)
    if constexpr (Strict && std::is_same_v<T,std::int64_t>) {
        if(__builtin_cpu_supports("avx2")) {
            const auto simd=reinsirk::detail::LISIndicesWithValuesAVX2Masks<std::uint32_t>(values);
            assert(simd==result);
        }
    }
#endif
    assert(result.size()==slow_length<Strict>(values));
    for(std::size_t i=0;i<result.size();++i) {
        assert(result[i]<values.size());
        if(i) {
            assert(result[i-1]<result[i]);
            assert(Strict ? values[result[i-1]]<values[result[i]] : !(values[result[i]]<values[result[i-1]]));
        }
    }
    assert(values==saved);
    ++checks;
}
void search_check(std::size_t count) {
#if !defined(SIRKIT_DISABLE_SIMD) && defined(__GNUC__) && !defined(__clang__) && __GNUC__ == 15 && __GNUC_MINOR__ == 2 && defined(__x86_64__)
    if(!__builtin_cpu_supports("avx2")) return;
    for(int mode=0;mode<4;++mode) {
        std::vector<std::int64_t> values(count+2);
        const auto origin=mode==2 ? std::numeric_limits<std::int64_t>::min() : mode==3 ? std::numeric_limits<std::int64_t>::max()-2*static_cast<std::int64_t>(values.size()) : std::int64_t{0};
        for(std::size_t i=0;i<values.size();++i)
            values[i]=origin+(mode==1 ? static_cast<std::int64_t>(i/3) : 2*static_cast<std::int64_t>(i));
        const std::size_t candidates[]={1,count/4+1,count/2+1,3*count/4+1,count,count+1};
        for(auto p:candidates) {
            for(int delta=-1;delta<=1;++delta) {
                if(delta<0 && values[p]==std::numeric_limits<std::int64_t>::min()) continue;
                if(delta>0 && values[p]==std::numeric_limits<std::int64_t>::max()) continue;
                const auto key=values[p]+delta;
                if(!(values.front()<key) || values.back()<key) continue;
                std::size_t expected=1;
                while(values[expected]<key) ++expected;
                assert(test_candidate_search(values,key)==expected);
                ++checks;
            }
        }
    }
#endif
}
int main() {
    for(std::size_t count=0;count<=160;++count) search_check(count);
    for(std::size_t count:{255,256,257,510,511,512,513,1022,1023,1024,1025,2046,2047,2048,2049,4093,4094,4095,4096,4097,4098,4200}) search_check(count);
    std::mt19937_64 rng(414109);
    for(int run=0;run<240;++run) {
        const auto n=static_cast<std::size_t>(run<180?run:rng()%180);
        std::vector<std::int64_t> values(n);
        for(std::size_t i=0;i<n;++i)
            values[i]=run%4==0 && i<n/2 ? static_cast<std::int64_t>(i) : static_cast<std::int64_t>(rng()%(run%3==0?7:1000));
        if(run%7==0) std::sort(values.begin(),values.end());
        if(run%11==0) std::reverse(values.begin(),values.end());
        if(n>1) {values.front()=std::numeric_limits<std::int64_t>::min();values.back()=std::numeric_limits<std::int64_t>::max();}
        sequence_check<true>(values);sequence_check<false>(values);
        std::vector<std::int32_t> narrow(values.begin(),values.end());sequence_check<true>(narrow);
    }
#ifndef SKIP_RUNTIME_CHECKS
    bool rejected=false;
    try { (void)LISIndices(std::vector<double>{0,std::numeric_limits<double>::quiet_NaN()}); }
    catch(const std::invalid_argument&) { rejected=true; }
    assert(rejected);
#endif
    std::cout<<"PASS checks="<<checks<<'\n';
}

